void NumericSensor::clearThresholdLog(
    std::optional<sdbusplus::message::object_path>& log)
{
    if (!log)
    {
        return;
    }

    try
    {
        lg2::resolve(*log);
    }
    catch (std::exception& ec)
    {
        lg2::error("Error trying to resolve: {LOG} : {ERROR}", "LOG", log->str,
                   "ERROR", ec);
    }
    log.reset();
}
